import { checkMode, getModeData, once, round } from '@iframe-resizer/common'
import { INIT, MESSAGE_ID } from '@iframe-resizer/common/consts'
import { HIGHLIGHT, ITALIC } from 'auto-console-group'

import { advise, assert, info, log } from '../console'
import settings from '../values/settings'
import state from '../values/state'

const sendFailed = once(() => advise(getModeData(4)))

export function displayTimeTaken(triggerEvent: string): void {
  if (!state.timerActive) return

  const timer = round(performance.now() - state.totalTime)
  const timeTaken =
    triggerEvent === INIT
      ? `Initialised iframe in %c${timer}ms`
      : `Size calculated in %c${timer}ms`

  log(timeTaken, HIGHLIGHT)
}

export function setTargetOrigin(
  targetOrigin: string | string[] | undefined,
): string | string[] {
  if (undefined === targetOrigin) targetOrigin = settings.targetOrigin
  else log(`Message targetOrigin: %c${targetOrigin}`, HIGHLIGHT)
  return targetOrigin
}

export function dispatchToParent(
  message: string,
  targetOrigin: string | undefined,
): boolean {
  const { mode } = settings
  const { sameOrigin, target } = state

  if (sameOrigin)
    try {
      window.parent.iframeParentListener(MESSAGE_ID + message)
    } catch (error) {
      if (checkMode(mode)) sendFailed()
      else throw new Error(error)
      return false
    }
  else {
    assert(target, 'Internal error: postMessage target is undefined')
    const origins = setTargetOrigin(targetOrigin)
    const originList = Array.isArray(origins) ? origins : [origins]

    for (const origin of originList) {
      ;(target as Window).postMessage(MESSAGE_ID + message, origin)
    }
  }

  return true
}

export default function dispatch(
  height: number,
  width: number,
  triggerEvent: string,
  msg?: string,
  targetOrigin?: string,
): void {
  const { parentId } = settings
  const { sameOrigin } = state
  const size = `${height}:${width}`
  const message = `${parentId}:${size}:${triggerEvent}${undefined === msg ? '' : `:${msg}`}`

  if (settings.mode < -1) return

  const success = dispatchToParent(message, targetOrigin)

  if (!success) return

  displayTimeTaken(triggerEvent)

  info(
    `Sending message to parent page via ${sameOrigin ? 'sameOrigin' : 'postMessage'}: %c%c${message}`,
    ITALIC,
    HIGHLIGHT,
  )
}
